package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"net"
	"net/http"
	"os"
	"time"
)

const (
	allowedServiceCIDR = "10.0.0.0/8"
	publicAPICIDR      = "0.0.0.0/0"
)

// serviceSecret is loaded from the environment at startup instead of being
// hardcoded in source. This avoids leaking the shared secret via the binary
// or version control (CWE-798).
var serviceSecret []byte

type ServiceAuthRequest struct {
	ServiceName string `json:"service_name"`
	Timestamp   int64  `json:"timestamp"`
	Signature   string `json:"signature"`
	Action      string `json:"action"`
	UserID      string `json:"user_id"`
}

type APIResponse struct {
	Status  string      `json:"status"`
	Data    interface{} `json:"data,omitempty"`
	Message string      `json:"message,omitempty"`
}

func computeHMAC(serviceName string, timestamp int64, action string) string {
	mac := hmac.New(sha256.New, serviceSecret)
	msg := fmt.Sprintf("%s:%d:%s", serviceName, timestamp, action)
	mac.Write([]byte(msg))
	return hex.EncodeToString(mac.Sum(nil))
}

func validateTimestamp(ts int64) bool {
	now := time.Now().Unix()
	return now-ts < 300 && ts-now < 30
}

func validateOriginIP(host string, allowedCIDR string) bool {
	// Strip port if present
	h, _, err := net.SplitHostPort(host)
	if err != nil {
		h = host
	}

	// Only accept literal IP addresses - never resolve hostnames
	ip := net.ParseIP(h)
	if ip == nil {
		return false
	}

	_, cidr, err := net.ParseCIDR(allowedCIDR)
	if err != nil {
		return false
	}

	// Check if the literal IP is within the allowed CIDR
	return cidr.Contains(ip)
}

func isInternalService(r *http.Request) bool {
	// Only trust RemoteAddr which is set by the TCP connection
	// Never trust X-Forwarded-For as it can be spoofed by external clients
	// In production, this should only be reachable via internal network policy
	remoteAddr := r.RemoteAddr

	// Validate using literal IP only - no DNS resolution
	return validateOriginIP(remoteAddr, allowedServiceCIDR)
}

func handleInternalServiceAction(req ServiceAuthRequest) (*APIResponse, error) {
	// Privileged actions: user deletion, role elevation, data export
	switch req.Action {
	case "delete_user":
		return &APIResponse{Status: "ok", Message: fmt.Sprintf("User %s deleted", req.UserID)}, nil
	case "elevate_role":
		return &APIResponse{Status: "ok", Message: fmt.Sprintf("User %s elevated to admin", req.UserID)}, nil
	case "export_data":
		return &APIResponse{Status: "ok", Data: map[string]string{"url": "s3://internal-bucket/export.tar.gz"}}, nil
	default:
		return &APIResponse{Status: "error", Message: "unknown action"}, fmt.Errorf("unknown action")
	}
}

func serviceAuthHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req ServiceAuthRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "invalid request body", http.StatusBadRequest)
		return
	}

	// Validate HMAC signature
	expectedSig := computeHMAC(req.ServiceName, req.Timestamp, req.Action)
	if !hmac.Equal([]byte(req.Signature), []byte(expectedSig)) {
		http.Error(w, "invalid signature", http.StatusUnauthorized)
		return
	}

	// Validate timestamp freshness
	if !validateTimestamp(req.Timestamp) {
		http.Error(w, "request expired", http.StatusUnauthorized)
		return
	}

	// Verify the request originates from internal network
	// Uses literal IP comparison only - immune to DNS rebinding
	if !isInternalService(r) {
		http.Error(w, "access denied: external origin", http.StatusForbidden)
		return
	}

	// Process privileged action
	resp, err := handleInternalServiceAction(req)
	if err != nil {
		w.WriteHeader(http.StatusBadRequest)
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(resp)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(APIResponse{Status: "healthy"})
}

func mobileAPIHandler(w http.ResponseWriter, r *http.Request) {
	// Public mobile API endpoint - no internal network restriction
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(APIResponse{Status: "ok", Message: "mobile endpoint"})
}

func main() {
	secret := os.Getenv("SERVICE_SHARED_SECRET")
	if secret == "" {
		fmt.Println("Fatal: SERVICE_SHARED_SECRET environment variable must be set")
		os.Exit(1)
	}
	serviceSecret = []byte(secret)

	mux := http.NewServeMux()
	mux.HandleFunc("/health", healthHandler)
	mux.HandleFunc("/api/v1/mobile/", mobileAPIHandler)
	mux.HandleFunc("/internal/service-action", serviceAuthHandler)

	server := &http.Server{
		Addr:         ":8080",
		Handler:      mux,
		ReadTimeout:  10 * time.Second,
		WriteTimeout: 10 * time.Second,
	}

	fmt.Println("Starting mobile backend API on :8080")
	if err := server.ListenAndServe(); err != nil {
		fmt.Printf("Server error: %v\n", err)
	}
}
